/**
 * Composable form-validation rules.
 *
 * A "rule" is a function (value) => string | null | Promise<string | null>:
 *   - returns an error message string when the value is invalid
 *   - returns null when the value is valid
 *   - may return a promise for async rules (e.g. `unique`)
 */

/** True for values considered "empty" (null, undefined, empty string). */
const isEmpty = (value) => value === null || value === undefined || value === '';

/**
 * Value is required (not null / undefined / '').
 * @param {string} msg error message
 */
export const required = (msg) => (value) => (isEmpty(value) ? msg : null);

/**
 * Minimum length in unicode code points (emoji-safe: '👍👍' counts as 2).
 * Empty values pass — combine with `required` if the field is mandatory.
 * @param {number} n minimum length
 * @param {string} msg error message
 */
export const minLength = (n, msg) => (value) => {
  if (isEmpty(value)) return null;
  const length = Array.from(String(value)).length; // code points, not UTF-16 units
  return length < n ? msg : null;
};

/**
 * Value must match the given regular expression.
 * Empty values pass — combine with `required` if the field is mandatory.
 * @param {RegExp} re pattern to match against
 * @param {string} msg error message
 */
export const pattern =
  (re, msg) =>
  (value) => {
    if (isEmpty(value)) return null;
    // Reset lastIndex so rules using global/sticky flags are reusable.
    re.lastIndex = 0;
    return re.test(String(value)) ? null : msg;
  };

/**
 * Async rule: invalid when `checkFn(value)` resolves truthy (e.g. value already taken).
 * @param {(value: any) => boolean | Promise<boolean>} checkFn
 * @param {string} msg error message
 */
export const unique = (checkFn, msg) => async (value) => {
  if (isEmpty(value)) return null;
  return (await checkFn(value)) ? msg : null;
};

/**
 * Compose rules into a single validator. Returns the first error message or
 * null. Sync rules are evaluated eagerly and in order; if none fails and any
 * rule is async, the returned validate() resolves to the first async error
 * (rules are awaited in order). With only sync rules, validate() stays fully
 * synchronous (returns string | null directly).
 *
 * @param {Array<(value: any) => string | null | Promise<string | null>>} rules
 * @returns {(value: any) => string | null | Promise<string | null>}
 */
export const compose = (rules) =>
  function validate(value) {
    let firstAsyncError = null;
    for (const rule of rules) {
      const result = rule(value);
      if (result instanceof Promise) {
        throwIfSettledSync(result);
        firstAsyncError = firstAsyncError ?? result.then((r) => r ?? firstAsyncError);
      } else if (result !== null && result !== undefined) {
        return result; // first sync failure wins immediately
      }
    }
    if (!firstAsyncError) return null;
    // Await pending async results in order; the earliest non-null wins.
    return (async () => {
      for (const rule of rules) {
        const result = await rule(value);
        if (result !== null && result !== undefined) return result;
      }
      return null;
    })();
  };

function throwIfSettledSync(promise) {
  void promise;
}

/**
 * Validate an object of values against a schema of per-field rule arrays.
 * Always returns a promise resolving to a map of `{ [field]: errorMessage }`
 * containing only fields with errors (empty object when everything passes).
 *
 * @param {Record<string, Array<(v: any) => string | null | Promise<string | null>>>} schema
 * @param {Record<string, any>} values
 * @returns {Promise<Record<string, string>>}
 */
export async function validateForm(schema, values) {
  const entries = await Promise.all(
    Object.entries(schema).map(async ([field, rules]) => [
      field,
      await compose(rules)(values?.[field]),
    ])
  );
  return Object.fromEntries(entries.filter(([, error]) => error !== null));
}

