import { describe, expect, it, vi } from 'vitest';
import { compose, minLength, pattern, required, unique, validateForm } from '../src/index.js';

describe('required', () => {
  it.each([null, undefined, ''])('fails for empty value %j', (value) => {
    expect(required('needed')(value)).toBe('needed');
  });

  it('passes for non-empty values', () => {
    expect(required('needed')('x')).toBeNull();
    expect(required('needed')(0)).toBeNull();
    expect(required('needed')(false)).toBeNull();
  });
});

describe('minLength', () => {
  it('counts unicode code points, not UTF-16 code units', () => {
    const rule = minLength(2, 'too short');
    // '👍' is one code point but length 2 in UTF-16
    expect(rule('👍')).toBe('too short');
    expect(rule('👍👍')).toBeNull();
    // surrogate pairs + BMP mix
    expect(minLength(3, 'nope')('👍a𝒳')).toBeNull();
    // astral-only string that looks long via .length but isn't by code points
    expect(minLength(4, 'nope')('𝒳𝒳'.repeat(1))).toBe('nope'); // 2 code points
  });

  it('empty values pass (pair with required)', () => {
    expect(minLength(5, 'too short')('')).toBeNull();
  });
});

describe('pattern', () => {
  it('validates against regex', () => {
    const rule = pattern(/^\d+$/, 'digits only');
    expect(rule('123')).toBeNull();
    expect(rule('12a')).toBe('digits only');
  });

  it('is reusable even with global flag', () => {
    const rule = pattern(/a/g, 'needs an a');
    expect(rule('b')).toBe('needs an a');
    expect(rule('b')).toBe('needs an a');
    expect(rule('cat')).toBeNull();
  });

  it('empty values pass', () => {
    expect(pattern(/^\d+$/, 'digits')('')).toBeNull();
  });
});

describe('compose', () => {
  it('returns null when everything passes', () => {
    const validate = compose([required('req'), minLength(3, 'short')]);
    expect(validate('hello')).toBeNull();
  });

  it('rule order determines which message wins (sync)', () => {
    const value = '';
    const reqFirst = compose([required('req!'), minLength(3, 'short!')]);
    const minFirst = compose([minLength(3, 'short!'), required('req!')]);
    expect(reqFirst(value)).toBe('req!');
    expect(minFirst(value)).toBe('short!');
  });

  it('rule order determines which message wins with async rules mixed in', async () => {
    const checkFn = vi.fn(async () => false);
    const rules = [minLength(3, 'short'), unique(checkFn, 'taken'), required('req')];
    const first = compose(rules);
    const reordered = compose([unique(checkFn, 'taken'), required('req'), minLength(3, 'short')]);

    // '' fails all three rules; first rule in order supplies the message
    await expect(first('')).resolves.toBe('short');
    await expect(reordered('')).resolves.toBe('taken');
  });

  it('stays synchronous when all rules are sync', () => {
    const validate = compose([required('req')]);
    expect(validate('')).toBe('req');
    expect(validate('ok')).toBeNull();
  });
});

describe('unique', () => {
  it('awaits stubbed checkFn and reports error when taken', async () => {
    const checkFn = vi.fn(async (v) => v === 'existing@example.com');
    const rule = unique(checkFn, 'already taken');
    await expect(rule('existing@example.com')).resolves.toBe('already taken');
    await expect(rule('free@example.com')).resolves.toBeNull();
    expect(checkFn).toHaveBeenCalledWith('existing@example.com');
  });

  it('handles non-promise return values from checkFn', async () => {
    const rule = unique(() => true, 'dup');
    await expect(rule('x')).resolves.toBe('dup');
  });
});

describe('validateForm', () => {
  const schema = {
    email: [required('email required'), pattern(/^[^@]+@[^@]+$/, 'invalid email')],
    name: [required('name required'), minLength(2, 'name too short')],
    username: [
      required('username required'),
      unique(async (v) => v === 'admin', 'username taken'),
    ],
  };

  it('resolves to a promise with {field: error} for invalid fields only', async () => {
    const errors = await validateForm(schema, {
      email: 'not-an-email',
      name: 'a',
      username: 'admin',
    });
    expect(errors).toEqual({
      email: 'invalid email',
      name: 'name too short',
      username: 'username taken',
    });
  });

  it('resolves to empty object when all fields valid', async () => {
    const errors = await validateForm(schema, {
      email: 'a@b.c',
      name: 'ab',
      username: 'someone-else',
    });
    expect(errors).toEqual({});
  });

  it('reports required errors for missing/empty fields and mixes sync+async', async () => {
    const errors = await validateForm(schema, {});
    expect(errors).toEqual({
      email: 'email required',
      name: 'name required',
      username: 'username required',
    });
  });

  it('per-field rule order decides the winning message per field', async () => {
    const errors = await validateForm(
      { name: [minLength(2, 'len wins'), required('req wins')] },
      { name: '' }
    );
    expect(errors).toEqual({ name: 'len wins' });
  });
});

